package cn.balltv.portal;
import java.io.*;import java.net.*;import java.util.*;
/** Small bounded GETs validate media, not merely an HTTP 200 or HTML player page. */
public final class SignalProbe {
 public static final class Result {public final String fingerprint,previewUrl,initUrl;public final byte[] media;public final int target;Result(String f,int t){this(f,t,"","");}Result(String f,int t,String p,String i){this(f,t,p,i,null);}Result(String f,int t,String p,String i,byte[] media){fingerprint=f;target=t;previewUrl=p;initUrl=i;this.media=media;}}
 static final class MediaBuffer extends ByteArrayOutputStream {
  boolean hasFlvVideo(){return flvVideo(buf,count);}
 }
 static boolean playlistHeader(byte[] bytes){
  int start=0;
  if(bytes.length>=3&&(bytes[0]&255)==239&&(bytes[1]&255)==187&&(bytes[2]&255)==191)start=3;
  while(start<bytes.length&&(bytes[start]&255)<=32)start++;
  String marker="#EXTM3U";
  if(bytes.length-start<marker.length())return false;
  for(int i=0;i<marker.length();i++)if(bytes[start+i]!=marker.charAt(i))return false;
  return true;
 }
 static byte[] read(String url,String referer,int max,long deadline)throws Exception{for(int redir=0;redir<4;redir++){if(!HttpData.publicUrl(url))throw new IOException("非公开视频地址");int remaining=(int)((deadline-System.nanoTime())/1000000);if(remaining<=0)throw new SocketTimeoutException();HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(Math.min(2200,remaining));c.setReadTimeout(Math.min(2200,remaining));c.setRequestProperty("User-Agent",Feeds.UA);c.setRequestProperty("Accept-Encoding","identity");c.setRequestProperty("Referer",referer);try{int status=c.getResponseCode();if(status>=300&&status<400){url=Feeds.absolute(url,c.getHeaderField("Location"));continue;}if(status!=200&&status!=206)throw new IOException("视频 HTTP "+status);MediaBuffer out=new MediaBuffer();int nextVideoCheck=8192;try(InputStream in=c.getInputStream()){byte[] bytes=new byte[4096];int n;while(out.size()<max&&(n=in.read(bytes,0,Math.min(bytes.length,max-out.size())))!=-1){out.write(bytes,0,n);if(System.nanoTime()>deadline)throw new SocketTimeoutException();if(out.size()>=nextVideoCheck){if(out.hasFlvVideo())break;nextVideoCheck=out.size()*2;}}}return out.toByteArray();}finally{c.disconnect();}}throw new IOException("视频重定向过多");}
 interface Fetch {byte[] get(String url,String ref,int max,long deadline)throws Exception;}
 public static Result check(String url,String referer)throws Exception{return check(url,referer,0,RequestBudget.deadline(System.nanoTime()+6500000000L),SignalProbe::read);}
 static Result check(String url,String ref,Fetch fetch)throws Exception{return check(url,ref,0,System.nanoTime()+6500000000L,fetch);}
 static Result check(String url,String ref,int depth,long deadline,Fetch fetch)throws Exception{if(depth>3)throw new IOException("播放列表嵌套过多");boolean playlist=url.toLowerCase(Locale.ROOT).contains(".m3u8");byte[] bytes=fetch.get(url,ref,playlist?262144:524288,deadline);if(playlistHeader(bytes)){String text=new String(bytes,"UTF-8").replace("\uFEFF","").trim();if(text.contains("#EXT-X-ENDLIST"))throw new IOException("该播放列表已结束");if(text.contains("#EXT-X-KEY")&&!text.contains("METHOD=NONE"))throw new IOException("此加密线路未完成轻量核验");ArrayList<String> links=new ArrayList<String>();int duration=6;String sequence="";for(String row:text.split("\\r?\\n")){row=row.trim();if(row.startsWith("#EXT-X-TARGETDURATION:"))try{duration=Integer.parseInt(row.substring(row.indexOf(':')+1));}catch(Exception ignored){}if(row.startsWith("#EXT-X-MEDIA-SEQUENCE:"))sequence=row.substring(row.indexOf(':')+1);if(!row.isEmpty()&&!row.startsWith("#"))links.add(Feeds.absolute(url,row));}if(links.isEmpty())throw new IOException("播放列表为空");String last=links.get(links.size()-1);if(text.contains("#EXT-X-STREAM-INF")){PreviewPlan master=PreviewPlan.parse(url,text);return check(master==null?links.get(0):master.media,ref,depth+1,deadline,fetch);}PreviewPlan plan=PreviewPlan.parse(url,text);String selected=plan==null?last:plan.media;byte[] media=fetch.get(selected,ref,262144,deadline);if(!tsVideo(media)&&!fragmentedMp4(media))throw new IOException("未读取到有效视频分片");String path=new URL(last).getPath();return new Result("hls:"+sequence+":"+path,duration,plan==null?last:plan.media,plan==null?"":plan.init,media);}
  if(!flvVideo(bytes))throw new IOException("未读取到 FLV 视频帧");return new Result("flv",0,"","",bytes);
 }
 public static boolean tsVideo(byte[] b){for(int offset=0;offset<Math.min(188,b.length);offset++){if((b[offset]&255)!=0x47)continue;int packets=0;boolean video=false;for(int p=offset;p+188<=b.length;p+=188){if((b[p]&255)!=0x47)break;packets++;for(int i=p+4;i+4<p+188;i++)if(b[i]==0&&b[i+1]==0&&b[i+2]==1&&(b[i+3]&255)>=0xe0&&(b[i+3]&255)<=0xef)video=true;if(packets>=3&&video)return true;}}return false;}
 static boolean fragmentedMp4(byte[] b){if(b.length<64)return false;int p=0;for(int boxes=0;boxes<4&&p+8<=b.length;boxes++){long size=((b[p]&255L)<<24)|((b[p+1]&255L)<<16)|((b[p+2]&255L)<<8)|(b[p+3]&255L);if(size<8)return false;String type=new String(b,p+4,4,java.nio.charset.Charset.forName("ISO-8859-1"));if(type.equals("moof")||type.equals("styp"))return true;if(size>b.length-p)return false;p+=(int)size;}return false;}
 public static boolean flvVideo(byte[] b){return flvVideo(b,b.length);}
 static boolean flvVideo(byte[] b,int length){if(length<13||b[0]!='F'||b[1]!='L'||b[2]!='V')return false;int p=((b[5]&255)<<24)|((b[6]&255)<<16)|((b[7]&255)<<8)|(b[8]&255);if(p<9||p>65536)return false;p+=4;int videos=0;long first=-1,last=-1;while(p+11<length){int type=b[p]&255,size=((b[p+1]&255)<<16)|((b[p+2]&255)<<8)|(b[p+3]&255);if(size<0||p+11L+size>length)break;if(type==9&&size>8){int codec=b[p+11]&15;if(codec==7&&b[p+12]==1){long timestamp=((b[p+7]&255L)<<24)|((b[p+4]&255L)<<16)|((b[p+5]&255L)<<8)|(b[p+6]&255L);if(first<0)first=timestamp;last=timestamp;videos++;}}p+=11+size+4;}return videos>=2&&last>first;}
}
